INSERT INTO sys_notice_read (id, notice_id, user_id, read_version, create_by, create_time) SELECT incoming.id, incoming.notice_id, incoming.user_id, incoming.read_version, incoming.create_by, incoming.create_time FROM (
SELECT #{receipt.id} AS id, #{receipt.noticeId} AS notice_id, #{receipt.userId} AS user_id, CAST(#{receipt.readVersion} AS SIGNED) AS read_version, #{receipt.createBy} AS create_by, #{receipt.createTime} AS create_time
) AS incoming ON DUPLICATE KEY UPDATE read_version = GREATEST(sys_notice_read.read_version, incoming.read_version)
